import math


def initial_bearing(
    origin: tuple[float, float], destination: tuple[float, float]
) -> float:
    for point in (origin, destination):
        if (
            not isinstance(point, tuple)
            or len(point) != 2
            or not all(
                isinstance(v, (int, float)) and not isinstance(v, bool)
                for v in point
            )
        ):
            raise TypeError("origin and destination must be 2-tuples of numbers")

    lat1, lon1 = (math.radians(v) for v in origin)
    lat2, lon2 = (math.radians(v) for v in destination)

    if lat1 == lat2 and lon1 == lon2:
        raise ValueError(
            "origin and destination are the same point; bearing is undefined"
        )

    delta_lon = lon2 - lon1
    x = math.sin(delta_lon) * math.cos(lat2)
    y = math.cos(lat1) * math.sin(lat2) - math.sin(lat1) * math.cos(lat2) * math.cos(
        delta_lon
    )
    bearing = math.degrees(math.atan2(x, y))
    return (bearing + 360.0) % 360.0
