```python
def monotone_chain(points: list[Point]) -> list[Point]:
    # Remove duplicates and sort lexicographically by (x, y)
    unique = sorted(set(points), key=lambda p: (p.x, p.y))

    if len(unique) <= 1:
        return unique

    def cross(o: Point, a: Point, b: Point) -> float:
        # Positive if o->a->b makes a counter-clockwise turn
        return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x)

    # Build lower hull
    lower: list[Point] = []
    for p in unique:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    # Build upper hull
    upper: list[Point] = []
    for p in reversed(unique):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Concatenate, dropping the last point of each half (it repeats the other's first)
    hull = lower[:-1] + upper[:-1]

    # Degenerate case: all points collinear, hull collapses to the two endpoints
    if len(hull) == 2 and len(unique) > 1:
        return [unique[0], unique[-1]]

    return hull
```

